from pathlib import Path
import json
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output'/'pdf'/'QSAR-X_Detailed_Workflow_Model_Output_Report.pdf'
registry=json.loads((ROOT/'models'/'target_registry.json').read_text(encoding='utf-8'))['targets']
NAVY=colors.HexColor('#10233E'); BLUE=colors.HexColor('#1768E5'); PALE=colors.HexColor('#EEF5FF'); INK=colors.HexColor('#17243A'); MUTED=colors.HexColor('#61738E'); LINE=colors.HexColor('#D7E1ED')
S=getSampleStyleSheet()
for name,parent,size,lead,color,space in [('TitleX','Title',27,32,NAVY,10),('SubX','Normal',11,16,MUTED,14),('H1X','Heading1',18,23,NAVY,9),('H2X','Heading2',12.5,16,NAVY,6),('BodyX','BodyText',9,13,INK,6),('SmallX','BodyText',7.25,9.5,INK,0),('FootX','Normal',7.5,9,MUTED,0)]:
 S.add(ParagraphStyle(name=name,parent=S[parent],fontName='Helvetica-Bold' if name in ['TitleX','H1X','H2X'] else 'Helvetica',fontSize=size,leading=lead,textColor=color,spaceAfter=space))
S.add(ParagraphStyle(name='Callout',parent=S['BodyText'],fontSize=9,leading=13,textColor=INK,backColor=PALE,borderColor=colors.HexColor('#BAD4F7'),borderWidth=.65,borderPadding=9,spaceAfter=10))
P=lambda x,sty='BodyX': Paragraph(str(x),S[sty])
def f(v,n=3):
 try:return f'{float(v):.{n}f}'
 except:return '-'
def t(data,w, repeat=1):
 tb=Table(data,colWidths=w,repeatRows=repeat,hAlign='LEFT'); tb.setStyle(TableStyle([
 ('GRID',(0,0),(-1,-1),.32,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),
 ('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,0),7),('FONTSIZE',(0,1),(-1,-1),7.1),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FC')])]))
 return tb
def hf(c,doc):
 c.saveState();w,h=A4;c.setStrokeColor(LINE);c.line(18*mm,h-15*mm,w-18*mm,h-15*mm);c.setFont('Helvetica-Bold',7.3);c.setFillColor(NAVY);c.drawString(18*mm,h-11*mm,'QSAR-X  |  Detailed workflow and model output report');c.setFont('Helvetica',7.2);c.setFillColor(MUTED);c.drawRightString(w-18*mm,h-11*mm,'Generated 15 October 2026');c.line(18*mm,13*mm,w-18*mm,13*mm);c.drawCentredString(w/2,8.5*mm,f'Page {doc.page}');c.restoreState()

story=[Spacer(1,22*mm),P('QSAR-X','TitleX'),P('Detailed workflow, training output, validation output, and target-wise model report','SubX'),P('Purpose','H1X'),P('This is the detailed companion report. It records every aggregate numeric output generated for each currently registered target-specific model: data volume, scaffold counts, train/validation/test split sizes, cross-validation comparison means and standard deviations, selected model, validation metrics, scaffold-held-out metrics, external-source metrics, structure-overlap removal count, and every external quality-gate result. It does not include all molecule-level assay rows or prediction rows because those are datasets rather than aggregate outputs; they remain in the local CSV artifacts and can be exported through the application.','BodyX'),P('<b>Truthful deployment status:</b> 20 target-specific models are loaded for screening. No model has passed every strict external validation gate. The detailed tables must not be interpreted as proof of commercial or prospective experimental accuracy.','Callout'),P('Contents','H2X'),P('1. Pipeline and data lineage<br/>2. Aggregate inventory table<br/>3. Detailed target dossiers (20 targets)<br/>4. Gate definition and interpretation<br/>5. Application output fields and saved artifacts','BodyX'),PageBreak()]

story += [P('1. Pipeline and data lineage','H1X'),P('Input: target choice plus molecular SMILES. For each target, ChEMBL target metadata and IC50 assay activities were retrieved. The curation path retained direct single-protein IC50 values, exact relation, positive numeric values, and nM units; structures were canonicalized using RDKit and duplicate structures were aggregated. pIC50 is calculated as 9 - log10(IC50 nM).','BodyX'),P('Training: chirality-aware Bemis-Murcko scaffold groups were split approximately 64/16/20 for training/validation/scaffold test. Training CV compared MedianBaseline, ExtraTrees, RandomForest, and SVR. The lowest train-CV RMSE candidate was saved as candidate_model.joblib. Current selected candidate family is ExtraTrees for the registered models.','BodyX'),P('Validation: BindingDB REST was used for an external-source non-overlap check by UniProt accession. Exact structures found in ChEMBL training were removed. PubChem BioAssay discovery and strict ingestion were also implemented; only non-ChEMBL sources with an explicit numeric IC50, unit, exact relation, SMILES, assay context, and publication provenance can be considered for the strict validator.','BodyX'),P('Software stack','H2X'),t([[P('Layer','SmallX'),P('Implementation','SmallX')],[P('Data and chemistry','SmallX'),P('ChEMBL activity endpoint data; BindingDB REST external-source checks; PubChem BioAssay PUG-REST discovery; RDKit canonicalization and Morgan fingerprints','SmallX')],[P('Training','SmallX'),P('Python 3.12.14; scikit-learn 1.9.1; RDKit 2026.09.1; ExtraTrees / RandomForest / SVR comparison','SmallX')],[P('Service','SmallX'),P('FastAPI versioned target registry and React/Vite web interface','SmallX')]], [42*mm,132*mm]),PageBreak()]

story += [P('2. Aggregate target inventory','H1X'),P('All values below come from the currently registered model version for each target. External n/RMSE are from the latest external report. “Not passed” means at least one strict quality gate is false.','BodyX')]
rows=[[P('Gene','SmallX'),P('ChEMBL','SmallX'),P('Model','SmallX'),P('n','SmallX'),P('Scaffold<br/>RMSE','SmallX'),P('Ext n','SmallX'),P('Ext<br/>RMSE','SmallX'),P('Ext<br/>MAE','SmallX'),P('Spearman','SmallX'),P('Gate','SmallX')]]
for x in sorted(registry,key=lambda z:z['gene']):
 ev=json.loads((ROOT/x['evaluation_report']).read_text()); ep=ROOT/x['external_validation_report']; ex=json.loads(ep.read_text()) if ep.exists() else {};m=ex.get('metrics_on_external_source_nonoverlap',{})
 rows.append([P(x['gene'],'SmallX'),P(x['target_id'],'SmallX'),P(x['model_version'],'SmallX'),P(ev.get('n_compounds'), 'SmallX'),P(f(ev.get('scaffold_test_metrics',{}).get('RMSE')),'SmallX'),P(m.get('n_compounds','-'),'SmallX'),P(f(m.get('RMSE_pIC50')),'SmallX'),P(f(m.get('MAE_pIC50')),'SmallX'),P(f(m.get('Spearman')),'SmallX'),P('PASS' if ex.get('quality_gates_passed') else 'Not passed','SmallX')])
story.append(t(rows,[16*mm,23*mm,18*mm,13*mm,20*mm,15*mm,18*mm,18*mm,18*mm,20*mm]));story.append(PageBreak())

for idx,x in enumerate(sorted(registry,key=lambda z:z['gene']),1):
 ev=json.loads((ROOT/x['evaluation_report']).read_text()); meta=json.loads((ROOT/'data'/'targets'/x['target_id']/'target_metadata.json').read_text()); ep=ROOT/x['external_validation_report']; ex=json.loads(ep.read_text()) if ep.exists() else {}; met=ex.get('metrics_on_external_source_nonoverlap',{}); sc=ev.get('split_counts',{}); st=ev.get('scaffold_test_metrics',{}); va=ev.get('validation_metrics',{})
 story += [P(f'3.{idx}. {x["gene"]} - {x["target_id"]}','H1X'),P(f'<b>Protein:</b> {meta.get("pref_name")} | <b>UniProt:</b> {meta.get("protein_accession")} | <b>Model version:</b> {x["model_version"]} | <b>Selected model:</b> {ev.get("selected_model_by_train_cv_rmse")}','SubX')]
 story += [P('Dataset and split output','H2X'),t([[P('Output','SmallX'),P('Value','SmallX')],[P('Curated compound count','SmallX'),P(ev.get('n_compounds'),'SmallX')],[P('Scaffold count','SmallX'),P(ev.get('n_scaffolds'),'SmallX')],[P('Train / validation / scaffold test','SmallX'),P(f"{sc.get('train')} / {sc.get('validation')} / {sc.get('scaffold_test')}",'SmallX')],[P('Train / validation / test scaffolds','SmallX'),P(f"{sc.get('train_scaffolds')} / {sc.get('validation_scaffolds')} / {sc.get('test_scaffolds')}",'SmallX')],[P('Fingerprint','SmallX'),P('Morgan, radius 2, 2,048 bits','SmallX')],[P('Candidate model SHA256','SmallX'),P(ev.get('candidate_model_sha256'),'SmallX')]], [61*mm,113*mm])]
 story += [P('Cross-validation comparison output','H2X')]
 cv=[[P('Model','SmallX'),P('CV R2 mean','SmallX'),P('CV R2 std','SmallX'),P('CV RMSE mean','SmallX'),P('CV RMSE std','SmallX'),P('CV MAE mean','SmallX'),P('CV MAE std','SmallX')]]
 for r in ev.get('cv_model_comparison',[]): cv.append([P(r.get('model'),'SmallX'),P(f(r.get('CV_R2_mean')),'SmallX'),P(f(r.get('CV_R2_std')),'SmallX'),P(f(r.get('CV_RMSE_mean')),'SmallX'),P(f(r.get('CV_RMSE_std')),'SmallX'),P(f(r.get('CV_MAE_mean')),'SmallX'),P(f(r.get('CV_MAE_std')),'SmallX')])
 story.append(t(cv,[29*mm,24*mm,23*mm,29*mm,26*mm,29*mm,25*mm]))
 story += [P('Selected candidate internal output','H2X'),t([[P('Evaluation','SmallX'),P('R2','SmallX'),P('RMSE pIC50','SmallX'),P('MAE pIC50','SmallX')],[P('Validation','SmallX'),P(f(va.get('R2')),'SmallX'),P(f(va.get('RMSE')),'SmallX'),P(f(va.get('MAE')),'SmallX')],[P('Scaffold-held-out test','SmallX'),P(f(st.get('R2')),'SmallX'),P(f(st.get('RMSE')),'SmallX'),P(f(st.get('MAE')),'SmallX')]], [53*mm,37*mm,43*mm,41*mm])]
 story += [P('External-source validation output','H2X')]
 if met:
  extrows=[[P('Metric / gate','SmallX'),P('Output','SmallX')],[P('Source','SmallX'),P(ex.get('source_database','-'),'SmallX')],[P('Exact training-structure overlaps removed','SmallX'),P(ex.get('exact_structure_overlaps_removed','-'),'SmallX')],[P('External non-overlap n','SmallX'),P(met.get('n_compounds','-'),'SmallX')],[P('External R2 / RMSE / MAE / Spearman','SmallX'),P(f"{f(met.get('R2'))} / {f(met.get('RMSE_pIC50'))} / {f(met.get('MAE_pIC50'))} / {f(met.get('Spearman'))}",'SmallX')]]
  for key,val in ex.get('quality_gates',{}).items(): extrows.append([P(key.replace('_',' '),'SmallX'),P(str(val),'SmallX')])
  extrows.append([P('Overall strict quality-gates passed','SmallX'),P(str(ex.get('quality_gates_passed')),'SmallX')]);extrows.append([P('External status','SmallX'),P(ex.get('status','-'),'SmallX')]); story.append(t(extrows,[75*mm,99*mm]))
 else: story.append(P('No external report is present for this target version.','Callout'))
 if idx < len(registry): story.append(PageBreak())

story += [PageBreak(),P('4. Strict validation gate definition','H1X')]
gates=[('Target accession','External target accession equals local target UniProt accession.'),('Endpoint','All retained records have standard_type IC50.'),('Unit','All retained records are normalized to nM.'),('Relation','All retained records have exact relation =.'),('Assay context','Every retained record has documented assay context.'),('Publication identifier','Every retained record has a documented publication ID.'),('Structure independence','No canonical external structure remains in training data.'),('Publication independence','No publication ID overlap remains with training provenance.'),('Minimum sample size','At least 30 external non-overlap compounds remain.'),('Metric floor','External RMSE <= 1.0; MAE <= 0.75; Spearman >= 0.50.'),('Reproducibility','Saved model SHA256 matches report candidate hash.'),('Source declared','Source name and source URL are non-empty.')]
story.append(t([[P('Gate','SmallX'),P('Required numeric / metadata condition','SmallX')]]+[[P(a,'SmallX'),P(b,'SmallX')] for a,b in gates],[52*mm,122*mm]))
story += [P('5. Application outputs and local artifacts','H1X'),P('Single prediction output: target ID/gene, input and canonical SMILES, predicted pIC50, predicted IC50 nM, dataset-level typical error, nearest training Tanimoto similarity, confidence label, model version and algorithm. Batch CSV output additionally provides a row-level status and error field. All outputs can be downloaded from the application as CSV. Prediction history is stored only in the browser local storage and can be exported as CSV.','BodyX'),P('Local target artifact layout','H2X'),P('data/targets/CHEMBL*/target_metadata.json, protein.fasta, IC50_raw.csv, IC50_clean.csv; models/CHEMBL*/baseline_v*/candidate_model.joblib, evaluation_report.json, model_comparison_cv.csv, split_assignments.csv, external_validation_report.json, external_validation_predictions.csv; models/target_registry.json; data/external_validation/pubchem_assay_inventory.json; data/external_validation/pubchem_independent/.','BodyX'),P('<b>Final status:</b> The tool is technically ready for target-specific screening across 20 registered targets. External validation remains an active evidence-collection and qualification task. Do not call the present models commercial-grade or clinically/experimentally validated until every required gate has passed and an expert review has been completed.','Callout')]

doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=21*mm,bottomMargin=18*mm,title='QSAR-X Detailed Workflow and Model Output Report',author='QSAR-X')
doc.build(story,onFirstPage=hf,onLaterPages=hf)
print(OUT)

